style.css:
@-moz-document domain("open.spotify.com") {
/* Opción 1: Por el destino del enlace (lo más efectivo) */
    a[href*="/premium"],
    a[href*="spotify.com/premium"],

    /* Opción 2: Por la etiqueta de accesibilidad (Aria Label) */
    /* Cubre inglés y español */
    button[aria-label="Upgrade to Premium"],
    button[aria-label="Mejorar tu cuenta"],
    button[title="Upgrade to Premium"],
    button[title="Mejorar tu cuenta"],

    /* Opción 3: Por ID de prueba (data-testid) */
    /* Spotify suele usar estos identificadores internos */
    [data-testid="upgrade-button"],
    [data-testid="top-bar-upgrade-button"] {
        display: none !important;
    }
}
